export const ntgdsGlobal = globalThis.__ntgds__ || {};
export const enhancements = ntgdsGlobal.enhancements = new Map();

globalThis.__ntgds__ = ntgdsGlobal;

if (typeof window !== 'undefined') {
    window.__ntgds__ = ntgdsGlobal;

    if (window.parent && window.parent !== window) {
        try {
            window.parent.__ntgds__ = ntgdsGlobal;
        } catch {}
    }
}

ntgdsGlobal.run = async function(opt = {}) {
    if (typeof opt === 'string') {
        const fn = enhancements.get(opt);
        if (typeof fn === 'function') {
            await Promise.resolve().then(() => fn());
        }
        return;
    }

    const { exclude, include } = opt;
    const runs = [...enhancements.entries()]
        .filter(([name, fn]) => {
            let result = typeof fn === 'function'
            // console.log(result, name, fn)
            if (result && Array.isArray(exclude) && !include) {
                result = !exclude.includes(name);
            }
            if (result && Array.isArray(include) && !exclude) {
                result = include.includes(name);
            }
            // console.log(fn)
            return result;
        })
            .map(([, fn]) => Promise.resolve().then(() => fn()));

    await Promise.allSettled(runs);
}
