import { enhancements } from "../../__ntgds__";

let accordionInitialized = false;

enhancements.set("accordion", () => {
  if (accordionInitialized) return;
  accordionInitialized = true;
  function closeItem(trigger, panel) {
    trigger.setAttribute("aria-expanded", "false");
    panel.hidden = true;
  }

  function openItem(trigger, panel) {
    trigger.setAttribute("aria-expanded", "true");
    panel.hidden = false;
  }

  /**
   * Suppresses the focus ring after a genuine pointer click, without
   * touching actual DOM focus (the trigger correctly stays focused for
   * keyboard/screen-reader users navigating sequentially). Browsers
   * dispatch the resulting `click` event with `detail: 0` when a button is
   * activated via keyboard (Enter/Space), and `detail >= 1` for a real
   * pointer click - that distinction is what drives this, not a guess at
   * :focus-visible's own (browser-dependent) heuristics.
   */
  function suppressRingIfPointerClick(trigger, event) {
    if (event.detail === 0) return;
    trigger.setAttribute("data-suppress-focus-ring", "");
    trigger.addEventListener("blur", function onBlur() {
      trigger.removeAttribute("data-suppress-focus-ring");
      trigger.removeEventListener("blur", onBlur);
    });
  }

  function updateToggleAllLabel(root) {
    var toggleAll = root.querySelector("[data-accordion-toggle-all]");
    if (!toggleAll) return;
    var triggers = root.querySelectorAll(".accordion-item__trigger");
    var allOpen =
      triggers.length > 0 &&
      Array.prototype.every.call(triggers, function (t) {
        return t.getAttribute("aria-expanded") === "true";
      });
    toggleAll.textContent = allOpen ? "Close all" : "Open all";
  }

  function handleTriggerClick(root, trigger) {
    var panel = document.getElementById(trigger.getAttribute("aria-controls"));
    if (!panel) return;
    var isOpen = trigger.getAttribute("aria-expanded") === "true";

    if (isOpen) {
      closeItem(trigger, panel);
    } else {
      openItem(trigger, panel);
    }

    updateToggleAllLabel(root);
  }

  function handleToggleAllClick(root) {
    var triggers = root.querySelectorAll(".accordion-item__trigger");
    var allOpen =
      triggers.length > 0 &&
      Array.prototype.every.call(triggers, function (t) {
        return t.getAttribute("aria-expanded") === "true";
      });

    triggers.forEach(function (trigger) {
      var panel = document.getElementById(
        trigger.getAttribute("aria-controls"),
      );
      if (!panel) return;
      if (allOpen) {
        closeItem(trigger, panel);
      } else {
        openItem(trigger, panel);
      }
    });

    updateToggleAllLabel(root);
  }

  /**
   * Delegated on document rather than bound to elements found at
   * DOMContentLoaded: the accordion's HTML can be injected into the page
   * well after the initial page load (e.g. Storybook's async story
   * rendering), so listeners attached only to elements present at
   * DOMContentLoaded would silently never fire for it.
   */
  document.addEventListener("click", function (event) {
    var trigger = event.target.closest(".accordion-item__trigger");
    if (trigger) {
      suppressRingIfPointerClick(trigger, event);
      var root = trigger.closest(".accordion");
      if (root) handleTriggerClick(root, trigger);
      return;
    }

    var toggleAll = event.target.closest("[data-accordion-toggle-all]");
    if (toggleAll) {
      var toggleAllRoot = toggleAll.closest(".accordion");
      if (toggleAllRoot) handleToggleAllClick(toggleAllRoot);
    }
  });
});
